package org.formasaloido;

import java.math.BigInteger;
import java.util.*;

/** Exact arithmetic and Spanish reading rules. No TTS, AI or platform dependencies. */
public final class MathLesson {
 public final String expression,result,reading,structure,grid;
 public final List<String> tokens=new ArrayList<>(),digits=new ArrayList<>(),rows=new ArrayList<>(),columns=new ArrayList<>(),steps=new ArrayList<>(),development=new ArrayList<>();
 private static final String[] SMALL={"cero","uno","dos","tres","cuatro","cinco","seis","siete","ocho","nueve","diez","once","doce","trece","catorce","quince","dieciséis","diecisiete","dieciocho","diecinueve","veinte","veintiuno","veintidós","veintitrés","veinticuatro","veinticinco","veintiséis","veintisiete","veintiocho","veintinueve"};
 private static final String[] TENS={"","","","treinta","cuarenta","cincuenta","sesenta","setenta","ochenta","noventa"},HUNDREDS={"","ciento","doscientos","trescientos","cuatrocientos","quinientos","seiscientos","setecientos","ochocientos","novecientos"};
 public static String cardinal(long n){if(n<0)return "menos "+cardinal(-n);if(n<30)return SMALL[(int)n];if(n<100)return TENS[(int)n/10]+(n%10==0?"":" y "+cardinal(n%10));if(n==100)return "cien";if(n<1000)return HUNDREDS[(int)n/100]+(n%100==0?"":" "+cardinal(n%100));if(n<1000000)return (n/1000==1?"mil":apocope(cardinal(n/1000))+" mil")+(n%1000==0?"":" "+cardinal(n%1000));if(n<1000000000000L)return (n/1000000==1?"un millón":apocope(cardinal(n/1000000))+" millones")+(n%1000000==0?"":" "+cardinal(n%1000000));return spelled(Long.toString(n));}
 private static String apocope(String s){return s.endsWith("veintiuno")?s.substring(0,s.length()-9)+"veintiún":s.endsWith("uno")?s.substring(0,s.length()-3)+"un":s;}
 public static String spelled(String s){StringBuilder out=new StringBuilder();for(char c:s.toCharArray()){if(out.length()>0)out.append(' ');out.append(c>='0'&&c<='9'?SMALL[c-'0']:c=='-'?"menos":c=='.'||c==','?"coma":String.valueOf(c));}return out.toString();}
 public static String number(String s){s=s.replace(',','.');boolean negative=s.startsWith("-");if(negative)s=s.substring(1);String[] p=s.split("\\.",-1);String whole=p[0].length()<=12?cardinal(Long.parseLong(p[0])):spelled(p[0]);return (negative?"menos ":"")+whole+(p.length==2?" coma "+spelled(p[1]):"");}
 static String symbol(String s){switch(s){case "+":return "signo más";case "-":return "signo menos";case "*":return "signo de multiplicación";case "/":return "signo de división";case "^":return "elevado a";case "(":return "abre paréntesis";case ")":return "cierra paréntesis";default:return number(s);}}
 public static final class Rational {
  public final BigInteger n,d;
  Rational(BigInteger a,BigInteger b){if(b.signum()==0)throw new IllegalArgumentException("No se puede dividir entre cero.");if(b.signum()<0){a=a.negate();b=b.negate();}BigInteger g=a.gcd(b);n=a.divide(g);d=b.divide(g);if(n.bitLength()>256||d.bitLength()>256)throw new IllegalArgumentException("El resultado excede el límite de cálculo del taller.");}
  static Rational parse(String s){int at=s.indexOf('.');return at<0?new Rational(new BigInteger(s),BigInteger.ONE):new Rational(new BigInteger(s.replace(".","")),BigInteger.TEN.pow(s.length()-at-1));}
  Rational apply(String op,Rational b){switch(op){case "+":return new Rational(n.multiply(b.d).add(b.n.multiply(d)),d.multiply(b.d));case "-":return new Rational(n.multiply(b.d).subtract(b.n.multiply(d)),d.multiply(b.d));case "*":return new Rational(n.multiply(b.n),d.multiply(b.d));case "/":return new Rational(n.multiply(b.d),d.multiply(b.n));default:if(!b.d.equals(BigInteger.ONE)||b.n.abs().compareTo(BigInteger.valueOf(12))>0)throw new IllegalArgumentException("El exponente debe ser un entero entre menos doce y doce.");int e=b.n.intValue();if(e==0&&n.signum()==0)throw new IllegalArgumentException("Cero elevado a cero no se define en este taller.");return e<0?new Rational(d.pow(-e),n.pow(-e)):new Rational(n.pow(e),d.pow(e));}}
  public String toString(){return n+(d.equals(BigInteger.ONE)?"":"/"+d);}
  public String speech(){return number(n.toString())+(d.equals(BigInteger.ONE)?"":" sobre "+number(d.toString()));}
 }
 private static final class Node {
  String op,text;Node a,b;Rational value;boolean resolved;
  Node(String t){text=t;value=Rational.parse(t);}
  Node(String o,Node x,Node y){op=o;a=x;b=y;value=y==null?new Rational(x.value.n.negate(),x.value.d):x.value.apply(o,y.value);}
  String read(){if(resolved)return value.speech();if(op==null)return number(text);if(b==null)return "opuesto de, "+a.read()+", fin del opuesto";if(op.equals("/"))return "fracción, numerador, "+a.read()+", denominador, "+b.read()+", fin de fracción";if(op.equals("^"))return "potencia, base, "+a.read()+", exponente, "+b.read()+", fin de potencia";return "inicio de grupo, "+a.read()+", "+symbol(op)+", "+b.read()+", fin de grupo";}
  void progress(Node root,List<String> out){if(op==null)return;a.progress(root,out);if(b!=null)b.progress(root,out);String before=root.read(),part=read(),fraction="";if(b!=null&&(op.equals("+")||op.equals("-"))&&(!a.value.d.equals(BigInteger.ONE)||!b.value.d.equals(BigInteger.ONE))){BigInteger common=a.value.d.divide(a.value.d.gcd(b.value.d)).multiply(b.value.d);fraction=" Tomamos el denominador común "+number(common.toString())+". El primer numerador queda "+number(a.value.n.multiply(common.divide(a.value.d)).toString())+" y el segundo "+number(b.value.n.multiply(common.divide(b.value.d)).toString())+". Operamos numeradores, conservamos denominador y simplificamos.";}resolved=true;out.add("Antes: "+before+". Cambio: resolvemos "+part+" y lo sustituimos por "+value.speech()+". Motivo: resolvemos primero los grupos interiores, las potencias, los productos y divisiones antes de las sumas y restas, según la estructura."+fraction+" Ahora: "+root.read()+".");}
  void explain(List<String> out){if(op==null)return;a.explain(out);if(b!=null)b.explain(out);if(b!=null&&(op.equals("+")||op.equals("-"))&&(!a.value.d.equals(BigInteger.ONE)||!b.value.d.equals(BigInteger.ONE))){BigInteger common=a.value.d.divide(a.value.d.gcd(b.value.d)).multiply(b.value.d),first=a.value.n.multiply(common.divide(a.value.d)),second=b.value.n.multiply(common.divide(b.value.d));out.add("Tomamos el denominador común "+number(common.toString())+". Reescribimos las fracciones como "+number(first.toString())+" sobre "+number(common.toString())+" y "+number(second.toString())+" sobre "+number(common.toString())+".");out.add("Operamos los numeradores y conservamos el denominador. Después simplificamos la fracción.");}out.add((b==null?"Tomamos el opuesto de "+a.value.speech():a.value.speech()+", "+symbol(op)+", "+b.value.speech())+". Resultado: "+value.speech()+".");}
 }
 private static final class Parser {
  final List<String> ts=new ArrayList<>();int at,depth;
  Parser(String s){if(s==null||s.length()>160)throw new IllegalArgumentException("La expresión admite hasta 160 caracteres.");s=s.replace('−','-').replace('×','*').replace('÷','/').replace("²","^2").replace("³","^3");for(int i=0;i<s.length();){char c=s.charAt(i);if(Character.isWhitespace(c)){i++;continue;}if(c>='0'&&c<='9'){int start=i++;while(i<s.length()&&Character.isDigit(s.charAt(i)))i++;if(i<s.length()&&(s.charAt(i)=='.'||s.charAt(i)==',')){i++;int decimal=i;while(i<s.length()&&Character.isDigit(s.charAt(i)))i++;if(i==decimal)throw new IllegalArgumentException("Faltan cifras después del separador decimal.");}String t=s.substring(start,i).replace(',','.');if(t.replace(".","").length()>12)throw new IllegalArgumentException("Cada número admite hasta doce cifras.");ts.add(t);}else if("+-*/^()".indexOf(c)>=0){ts.add(String.valueOf(c));i++;}else throw new IllegalArgumentException("Símbolo no admitido: "+c+". Usa números, paréntesis y + - * / ^.");if(ts.size()>64)throw new IllegalArgumentException("Máximo 64 símbolos por expresión.");}}
  boolean take(String s){if(at<ts.size()&&ts.get(at).equals(s)){at++;return true;}return false;}
  Node sum(){Node n=product();while(at<ts.size()&&(ts.get(at).equals("+")||ts.get(at).equals("-"))){String op=ts.get(at++);n=new Node(op,n,product());}return n;}
  Node product(){Node n=unary();while(at<ts.size()&&(ts.get(at).equals("*")||ts.get(at).equals("/"))){String op=ts.get(at++);n=new Node(op,n,unary());}return n;}
  Node unary(){if(++depth>16)throw new IllegalArgumentException("Demasiados niveles de agrupación.");try{if(take("+"))return unary();if(take("-"))return new Node("-",unary(),null);Node n=primary();if(take("^"))n=new Node("^",n,unary());return n;}finally{depth--;}}
  Node primary(){if(take("(")){Node n=sum();if(!take(")"))throw new IllegalArgumentException("Falta cerrar un paréntesis.");return n;}if(at>=ts.size()||!Character.isDigit(ts.get(at).charAt(0)))throw new IllegalArgumentException("Se esperaba un número o un paréntesis.");return new Node(ts.get(at++));}
 }
 public MathLesson(String input){if(MathAdvanced.accepts(input)){MathAdvanced.Result a=MathAdvanced.create(input);expression=a.expression;result=a.result;reading=a.reading;structure=a.structure;grid=expression+"\nResultado: "+result;tokens.addAll(a.tokens);for(String t:MathAdvanced.lex(expression)){String word=MathAdvanced.word(t);if(!word.isEmpty())digits.add(Character.isDigit(t.charAt(0))?spelled(t):word);}rows.add("Expresión: "+reading);rows.add("Resultado: "+MathAdvanced.resultSpeech(result));columns.add("La disposición en columnas se ofrece para dos enteros. Aquí puedes navegar por símbolos, estructura y pasos.");steps.addAll(a.steps);steps.add("Resultado: "+MathAdvanced.resultSpeech(result));buildDevelopment(null);return;}Parser p=new Parser(input);Node root=p.sum();if(p.at!=p.ts.size())throw new IllegalArgumentException("Sobran símbolos o falta un operador.");expression=String.join(" ",p.ts);result=root.value.toString();StringBuilder words=new StringBuilder();for(String t:p.ts){tokens.add(symbol(t));digits.add(Character.isDigit(t.charAt(0))?spelled(t):symbol(t));if(words.length()>0)words.append(", ");words.append(symbol(t));}reading=words.toString();structure=root.read();root.explain(steps);if(steps.isEmpty())steps.add("El número es "+root.value.speech()+".");String visual=expression+" = "+result;
  if(root.op!=null&&root.b!=null&&root.a.op==null&&root.b.op==null&&root.a.text.matches("[0-9]{1,6}")&&root.b.text.matches("[0-9]{1,6}")){
   int a=Integer.parseInt(root.a.text),b=Integer.parseInt(root.b.text);if("+-*/".contains(root.op)){
    int width=Math.max(Math.max(root.a.text.length(),root.b.text.length()),result.length());String line=String.join("",Collections.nCopies(width+2,"─"));visual=String.format(Locale.ROOT,"%"+(width+2)+"s\n%s %"+width+"s\n%s\n%"+(width+2)+"s",a,root.op,b,line,result);
    rows.add("Fila uno, primer número: "+cardinal(a)+".");rows.add("Fila dos, "+symbol(root.op)+", segundo número: "+cardinal(b)+".");rows.add("Línea horizontal de separación.");rows.add("Resultado exacto: "+root.value.speech()+".");
    int count=Math.max(Integer.toString(a).length(),Integer.toString(b).length());for(int i=count-1;i>=0;i--)columns.add(column(a,b,i));
    List<String> detailed=procedure(a,b,root.op);if(!detailed.isEmpty()){steps.clear();steps.addAll(detailed);steps.add("Resultado exacto: "+root.value.speech()+".");}
   }
  }
  if(rows.isEmpty()){rows.add("Expresión en una fila: "+reading+".");rows.add("Resultado exacto: "+root.value.speech()+".");columns.add("Esta expresión no tiene una disposición en columnas. Usa la lectura por símbolos o por estructura.");}grid=visual;buildDevelopment(root);
 }
 private void buildDevelopment(Node root){
  development.add("Punto de partida: "+reading+". Recorre una etapa cada vez; puedes repetirla o volver atrás. No avanzamos automáticamente.");
  boolean vertical=rows.size()>2;
  if(root!=null&&!vertical&&root.op!=null)root.progress(root,development);else development.addAll(steps);
  development.add("Cierre: "+(root==null?MathAdvanced.resultSpeech(result):root.value.speech())+". Vuelve al punto de partida para repasar el recorrido.");
 }
 private static int digit(int n,int pos){for(int i=0;i<pos;i++)n/=10;return n%10;}
 private static String place(int p){return new String[]{"unidades","decenas","centenas","unidades de millar","decenas de millar","centenas de millar","millones"}[p];}
 private static String column(int a,int b,int i){long power=1;for(int j=0;j<i;j++)power*=10;return "Columna de "+place(i)+". Primera fila: "+(a<power?"espacio vacío":cardinal(digit(a,i)))+". Segunda fila: "+(b<power?"espacio vacío":cardinal(digit(b,i)))+".";}
 private static List<String> procedure(int a,int b,String op){List<String> out=new ArrayList<>();int count=Math.max(Integer.toString(a).length(),Integer.toString(b).length());
  if(op.equals("+")){int carry=0;for(int i=0;i<count;i++){int x=digit(a,i),y=digit(b,i),total=x+y+carry;out.add("Columna de "+place(i)+". "+cardinal(x)+" más "+cardinal(y)+(carry>0?" más una llevada":"")+" son "+cardinal(total)+". Escribe "+cardinal(total%10)+(total>=10?" y lleva una a la columna siguiente.":". No hay llevada.") );carry=total/10;}if(carry>0)out.add("Escribe la llevada final, uno, en "+place(count)+".");}
  if(op.equals("-")&&a>=b){int borrow=0;for(int i=0;i<count;i++){int original=digit(a,i),x=original-borrow,y=digit(b,i);String text="Columna de "+place(i)+". Arriba hay "+cardinal(original)+(borrow>0?(x<0?"; esta columna debe una unidad a la anterior":", después de ceder una unidad quedan "+cardinal(x)):"")+". Abajo hay "+cardinal(y)+". ";borrow=x<y?1:0;if(borrow>0){x+=10;text+="Tomamos una unidad de la columna siguiente, equivalente a diez en esta columna. Quedan "+cardinal(x)+". ";}out.add(text+cardinal(x)+" menos "+cardinal(y)+" son "+cardinal(x-y)+". Escribe "+cardinal(x-y)+".");}}
  if(op.equals("-")&&a<b){out.add("El primer número es menor. Calculamos "+cardinal(b)+" menos "+cardinal(a)+" y cambiamos el signo.");out.addAll(procedure(b,a,"-"));out.add("La diferencia lleva signo negativo.");}
  if(op.equals("*")){String ds=Integer.toString(b);for(int i=0;i<ds.length();i++){int d=digit(b,i);out.add("Producto parcial de "+place(i)+": "+cardinal(a)+" por "+cardinal(d)+" da "+cardinal((long)a*d)+". "+(i==0?"Se alinea con las unidades.":"Se desplaza "+cardinal(i)+" posiciones a la izquierda."));}out.add("Sumamos los productos parciales según su posición: "+cardinal((long)a*b)+".");}
  if(op.equals("/")&&b!=0){int rem=0;String ds=Integer.toString(a);for(int i=0;i<ds.length();i++){int next=rem*10+(ds.charAt(i)-'0'),q=next/b;out.add("Bajamos la cifra "+cardinal(ds.charAt(i)-'0')+". Formamos "+cardinal(next)+". Cabe "+cardinal(q)+" veces "+cardinal(b)+"; restamos "+cardinal((long)q*b)+" y queda "+cardinal(next%b)+".");rem=next%b;}out.add("Cociente entero: "+cardinal(a/b)+". Resto: "+cardinal(a%b)+". "+(a%b==0?"La división es exacta.":"El resultado exacto se conserva como fracción; no se redondea."));}return out;
 }
 public Map<String,Object> data(){Map<String,Object> m=new LinkedHashMap<>();m.put("expression",expression);m.put("result",result);m.put("reading",reading);m.put("structure",structure);m.put("grid",grid);m.put("tokens",tokens);m.put("digits",digits);m.put("rows",rows);m.put("columns",columns);m.put("steps",steps);m.put("development",development);m.put("project",project());m.put("genny",genny());m.put("script",script());return m;}
 public String json(){return Json.write(data());}
 public String project(){Map<String,Object> m=new LinkedHashMap<>();m.put("schema","formas-math-v1");m.put("expression",expression);return Json.write(m);}
 public static String planeProject(int kind,double x,double y){plane(kind);point(x,y);return Json.write(Json.object("schema","formas-math-plane-v1","plane",kind,"x",x,"y",y));}
 public static Map<String,Object> loadPlane(String json){Object parsed=Json.parse(json);if(!(parsed instanceof Map))throw new IllegalArgumentException("Plano JSON no válido.");Map<?,?> m=(Map<?,?>)parsed;if(!"formas-math-plane-v1".equals(m.get("schema"))||!(m.get("plane") instanceof Number)||!(m.get("x") instanceof Number)||!(m.get("y") instanceof Number))throw new IllegalArgumentException("Formato de plano no compatible.");double id=((Number)m.get("plane")).doubleValue(),x=((Number)m.get("x")).doubleValue(),y=((Number)m.get("y")).doubleValue();if(id!=Math.rint(id))throw new IllegalArgumentException("El tipo de plano debe ser entero.");int kind=(int)id;plane(kind);point(x,y);return Json.object("plane",kind,"x",x,"y",y,"description",at(kind,x,y));}
 public static MathLesson load(String json){Object value=Json.parse(json);if(!(value instanceof Map)||!"formas-math-v1".equals(((Map<?,?>)value).get("schema"))||!(((Map<?,?>)value).get("expression") instanceof String))throw new IllegalArgumentException("No es un ejercicio matemático compatible.");return new MathLesson((String)((Map<?,?>)value).get("expression"));}
 public String script(){return "Expresión: "+reading+". Estructura: "+structure+". "+String.join(" ",development);}
 public String genny(){Map<String,Object> params=new LinkedHashMap<>();params.put("lang","es");params.put("voice","male");Map<String,Object> layer=new LinkedHashMap<>();layer.put("type","speech");layer.put("text",script());layer.put("params",params);Map<String,Object> m=new LinkedHashMap<>();m.put("out","leccion-matematica.wav");m.put("layers",Collections.singletonList(layer));return Json.write(m);}
 public static Geometry.Point point(double x,double y){if(!Double.isFinite(x)||!Double.isFinite(y)||Math.abs(x)>5||Math.abs(y)>5)throw new IllegalArgumentException("Las coordenadas deben estar entre menos cinco y cinco.");return new Geometry.Point(300+x*40,225-y*40);}
 public static String coordinate(double x,double y){point(x,y);String where=x==0&&y==0?"Origen.":x==0?"Sobre el eje ye.":y==0?"Sobre el eje equis.":"Cuadrante "+(x>0?(y>0?"primero":"cuarto"):(y>0?"segundo":"tercero"))+".";return "Equis "+number(trim(x))+", ye "+number(trim(y))+". "+where;}
 private static String trim(double x){return java.math.BigDecimal.valueOf(x==0?0:x).stripTrailingZeros().toPlainString();}
 public static final String[] PLANES={"Ejes y puntos A y B","Recta diagonal","Cuadrado","Circunferencia","Parábola","Seno, equis en radianes","Coseno, equis en radianes","Tangente entre menos 1,2 y 1,2 radianes"};
 public static Map<String,Object> trace(int kind,int index){Geometry g=plane(kind);List<Geometry.Point> points=new ArrayList<>();for(int i=2;i<g.shapes.size();i++){Geometry.Shape s=g.shapes.get(i);points.addAll(s.points);if(s.closed)points.add(s.points.get(0));}int at=Math.max(0,Math.min(points.size()-1,index));Geometry.Point p=points.get(at);Map<String,Object> data=pointData(kind,(p.x-300)/40,(225-p.y)/40,at,points.size());if(at==points.size()-1)data.put("description",data.get("description")+(g.shapes.get(g.shapes.size()-1).closed?" Fin del recorrido cerrado; volvimos al inicio.":" Fin del trazo disponible."));return data;}
 public static Map<String,Object> project(int kind,double x){point(x,0);double y;if(kind==1&&Math.abs(x)<=4)y=.75*x;else if(kind==4&&Math.abs(x)<=2.5)y=x*x-2;else if(kind==5)y=Math.sin(x);else if(kind==6)y=Math.cos(x);else if(kind==7&&Math.abs(x)<=1.2)y=Math.tan(x);else throw new IllegalArgumentException("Esta figura no ofrece un único valor de ye en ese intervalo. Usa los puntos del contorno; en la parábola usa equis entre menos 2,5 y 2,5.");return pointData(kind,x,y,-1,0);}
 private static Map<String,Object> pointData(int kind,double x,double y,int index,int count){x=Math.rint(x*10)/10;y=Math.rint(y*10)/10;return Json.object("plane",kind,"x",x,"y",y,"index",index,"count",count,"description",(index>=0?"Punto "+(index+1)+" de "+count+". ":"")+"Coordenadas redondeadas a una décima. "+at(kind,x,y));}
 private static Geometry.Shape shape(boolean closed,boolean curve,double... xy){List<Geometry.Point> p=new ArrayList<>();for(int i=0;i<xy.length;i+=2)p.add(point(xy[i],xy[i+1]));return new Geometry.Shape(p,closed,curve);}
 public static Geometry plane(int kind){if(kind<0||kind>=PLANES.length)throw new IllegalArgumentException("Ejemplo de plano desconocido.");List<Geometry.Shape> shapes=new ArrayList<>();shapes.add(shape(false,false,-5,0,5,0));shapes.add(shape(false,false,0,-5,0,5));if(kind==0){shapes.add(shape(false,false,-2,3));shapes.add(shape(false,false,3,-2));}if(kind==1)shapes.add(shape(false,false,-4,-3,4,3));if(kind==2)shapes.add(shape(true,false,-3,-2,-1,-2,-1,0,-3,0));if(kind==3){List<Geometry.Point> pts=new ArrayList<>();for(int i=0;i<96;i++){double t=i*Math.PI*2/96;pts.add(point(2+1.5*Math.cos(t),1+1.5*Math.sin(t)));}shapes.add(new Geometry.Shape(pts,true,true));}if(kind==4){List<Geometry.Point> pts=new ArrayList<>();for(int i=0;i<=80;i++){double x=-2.5+i/16.0;pts.add(point(x,x*x-2));}shapes.add(new Geometry.Shape(pts,false,true));}if(kind>=5){List<Geometry.Point> pts=new ArrayList<>();double min=kind==7?-1.2:-5,max=-min;for(int i=0;i<=160;i++){double x=min+(max-min)*i/160.0;pts.add(point(x,kind==5?Math.sin(x):kind==6?Math.cos(x):Math.tan(x)));}shapes.add(new Geometry.Shape(pts,false,true));}return new Geometry(0,shapes);}
 public static String planeOverview(int kind){plane(kind);return PLANES[kind]+". Origen en el centro; equis crece a la derecha, ye hacia arriba. Cada unidad equivale a cuarenta unidades del lienzo. Ejes de menos cinco a cinco. "+new String[]{"A está en menos dos, tres; B en tres, menos dos.","Segmento recto desde menos cuatro, menos tres hasta cuatro, tres.","Cuadrado con esquinas en menos tres, menos dos; menos uno, menos dos; menos uno, cero; menos tres, cero.","Circunferencia de centro dos, uno y radio uno coma cinco.","Parábola ye igual a equis al cuadrado menos dos. Vértice en cero, menos dos.","Ye igual a seno de equis. Equis se mide en radianes; ye entre menos uno y uno.","Ye igual a coseno de equis. Equis se mide en radianes; ye entre menos uno y uno.","Fragmento de ye igual a tangente de equis, de menos uno coma dos a uno coma dos radianes. No incluye sus asíntotas."}[kind];}
 public static String at(int kind,double x,double y){Geometry g=plane(kind);Geometry.Point p=point(x,y);StringBuilder s=new StringBuilder(coordinate(x,y));boolean hit=false;for(int i=2;i<g.shapes.size();i++){Geometry.Shape sh=g.shapes.get(i);double best=Double.MAX_VALUE;for(Geometry.Point q:sh.points)best=Math.min(best,p.distance(q));if(!sh.curve&&best<9){s.append(sh.points.size()==1?" Punto "+(i==2?"A.":"B."):sh.closed?" Esquina del cuadrado.":" Extremo del segmento.");hit=true;}else{for(int j=1;j<sh.points.size();j++)best=Math.min(best,distance(p,sh.points.get(j-1),sh.points.get(j)));if(sh.closed)best=Math.min(best,distance(p,sh.points.get(sh.points.size()-1),sh.points.get(0)));if(best<9){s.append(sh.curve?" Trazo curvo.":" Línea recta.");if(kind==4&&p.distance(point(0,-2))<9)s.append(" Vértice de la parábola; punto mínimo.");hit=true;}}}if(Math.abs(x)<.2)s.append(" Eje vertical ye.");if(Math.abs(y)<.2)s.append(" Eje horizontal equis.");if(!hit&&Math.abs(x)>=.2&&Math.abs(y)>=.2)s.append(kind==2&&x>-3&&x<-1&&y>-2&&y<0?" Interior del cuadrado, sin borde en esta posición.":kind==3&&Math.hypot(x-2,y-1)<1.5?" Interior de la circunferencia, sin borde en esta posición.":" Espacio vacío del dibujo matemático.");return s.toString();}
 private static double distance(Geometry.Point p,Geometry.Point a,Geometry.Point b){double dx=b.x-a.x,dy=b.y-a.y,d=dx*dx+dy*dy,t=d==0?0:Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/d));return p.distance(new Geometry.Point(a.x+t*dx,a.y+t*dy));}
}
